import 'package:flutter/material.dart';
import '../services/app_state.dart';
import '../widgets/incident_card.dart';
import 'incident_detail_screen.dart';
class HistoryScreen extends StatefulWidget {const HistoryScreen({super.key,required this.state,required this.role,required this.onBack});final AppState state;final String role;final VoidCallback onBack;@override State<HistoryScreen> createState()=>_HistoryScreenState();}
class _HistoryScreenState extends State<HistoryScreen>{String status='Todos';String dept='Todos';String q='';
@override Widget build(BuildContext context){final list=widget.state.incidents.where((i)=>(status=='Todos'||i.status==status)&&(dept=='Todos'||i.department==dept)&&(q.isEmpty||i.description.toLowerCase().contains(q.toLowerCase())||i.location.toLowerCase().contains(q.toLowerCase()))).toList();return Scaffold(appBar:AppBar(leading:IconButton(onPressed:widget.onBack,icon:const Icon(Icons.arrow_back)),title:const Text('Historial')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(decoration:const InputDecoration(labelText:'Buscar por descripción o ubicación',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()),onChanged:(v)=>setState(()=>q=v)),const SizedBox(height:10),Row(children:[Expanded(child:DropdownButtonFormField(value:status,decoration:const InputDecoration(labelText:'Estado'),items:['Todos','Pendiente','En proceso','Finalizado'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>status=v!))),const SizedBox(width:10),Expanded(child:DropdownButtonFormField(value:dept,decoration:const InputDecoration(labelText:'Departamento'),items:['Todos','Recepción','Ama de Llaves','Limpieza','Mantenimiento'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>dept=v!))) ]),const SizedBox(height:12),Text('${list.length} resultado(s)'),...list.map((i)=>IncidentCard(incident:i,onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>IncidentDetailScreen(state:widget.state,incident:i,role:widget.role)))))]));}}